package com.stressdetector.mobile.ml.rag

import android.content.Context

/**
 * Runtime projection of configs/rag.yaml. The checked-in asset is generated by
 * scripts/generate_rag_runtime_contract.py and verified before every app build.
 */
data class RagRuntimeContract(
    val configVersion: String,
    val sourceConfigSha256: String,
    val contractSha256: String,
    val embedding: Embedding,
    val chunking: Chunking,
    val retrieval: Retrieval,
    val persona: Persona
) {
    data class Embedding(
        val model: String,
        val revision: String,
        val dimensions: Int,
        val maximumTokens: Int,
        val queryPrefix: String,
        val passagePrefix: String,
        val pooling: String,
        val normalization: String
    )

    data class Chunking(val policyVersion: String, val targetTokens: Int, val hardMaximumTokens: Int, val overlapTokens: Int)

    data class Retrieval(
        val semanticCandidates: Int,
        val lexicalCandidates: Int,
        val rrfK: Int,
        val mmrLambda: Float,
        val maxEvidenceChunks: Int,
        val maxChunksPerDocument: Int,
        val maxChunksPerPage: Int,
        val lexicalBackend: String,
        val productionStatus: String,
        val uncalibratedBehavior: String
    )

    data class Persona(val focusNoteMaxWords: Int)

    init {
        require(configVersion.isNotBlank()) { "rag_config_version_missing" }
        require(sourceConfigSha256.matches(SHA256)) { "rag_source_checksum_invalid" }
        require(contractSha256.matches(SHA256)) { "rag_contract_checksum_invalid" }
        require(embedding.model == E5_MODEL) { "rag_embedding_model_mismatch" }
        require(embedding.revision == E5_REVISION) { "rag_embedding_revision_mismatch" }
        require(embedding.dimensions == LocalEmbeddingModel.EMBEDDING_DIMENSIONS) { "rag_embedding_dimension_mismatch" }
        require(embedding.maximumTokens == LocalEmbeddingModel.MAX_TOKENS) { "rag_embedding_max_tokens_mismatch" }
        require(embedding.queryPrefix == EmbeddingInputKind.QUERY.prefix) { "rag_embedding_query_prefix_mismatch" }
        require(embedding.passagePrefix == EmbeddingInputKind.PASSAGE.prefix) { "rag_embedding_passage_prefix_mismatch" }
        require(embedding.pooling == "attention_mask_mean") { "rag_embedding_pooling_mismatch" }
        require(embedding.normalization == "l2") { "rag_embedding_normalization_mismatch" }
        require(chunking.targetTokens == DEFAULT_CHUNK_TARGET_TOKENS) { "rag_chunk_target_mismatch" }
        require(chunking.hardMaximumTokens == DEFAULT_CHUNK_HARD_MAXIMUM_TOKENS) { "rag_chunk_max_mismatch" }
        require(chunking.overlapTokens == DEFAULT_CHUNK_OVERLAP_TOKENS) { "rag_chunk_overlap_mismatch" }
        require(chunking.policyVersion == TextChunker.POLICY_VERSION) { "rag_chunk_policy_mismatch" }
        require(retrieval.semanticCandidates == DEFAULT_CANDIDATE_LIMIT) { "rag_semantic_candidate_mismatch" }
        require(retrieval.lexicalCandidates == DEFAULT_CANDIDATE_LIMIT) { "rag_lexical_candidate_mismatch" }
        require(retrieval.rrfK == DEFAULT_RRF_K) { "rag_rrf_mismatch" }
        require(retrieval.mmrLambda == DEFAULT_MMR_LAMBDA) { "rag_mmr_mismatch" }
        require(retrieval.maxEvidenceChunks == DEFAULT_MAX_EVIDENCE_CHUNKS) { "rag_evidence_limit_mismatch" }
        require(retrieval.maxChunksPerDocument == DEFAULT_MAX_CHUNKS_PER_DOCUMENT) { "rag_document_limit_mismatch" }
        require(retrieval.maxChunksPerPage == DEFAULT_MAX_CHUNKS_PER_PAGE) { "rag_page_limit_mismatch" }
        require(retrieval.lexicalBackend == SQLITE_FTS5_BM25) { "rag_lexical_backend_mismatch" }
        require(retrieval.productionStatus == BLOCKED_PRODUCTION_STATUS) { "rag_production_status_mismatch" }
        require(retrieval.uncalibratedBehavior == ABSTAIN) { "rag_uncalibrated_behavior_mismatch" }
        require(persona.focusNoteMaxWords == DEFAULT_FOCUS_NOTE_MAX_WORDS) { "rag_persona_word_limit_mismatch" }
    }

    fun requireCompatibleWith(runtime: E5EmbeddingRuntimeContract) {
        require(embedding.revision == runtime.revision) { "rag_embedding_revision_mismatch" }
        require(embedding.dimensions == runtime.dimensions) { "rag_embedding_runtime_dimension_mismatch" }
        require(embedding.maximumTokens == runtime.maximumTokens) { "rag_embedding_runtime_max_tokens_mismatch" }
    }

    fun chunkingConfig(): TextChunker.Config = TextChunker.Config(
        targetTokens = chunking.targetTokens,
        hardMaximumTokens = chunking.hardMaximumTokens,
        overlapTokens = chunking.overlapTokens,
        policyVersion = chunking.policyVersion
    )

    fun retrievalPolicy(binding: RetrievalPolicyBinding): LocalRagRetrievalPolicy = LocalRagRetrievalPolicy(
        semanticCandidateLimit = retrieval.semanticCandidates,
        lexicalCandidateLimit = retrieval.lexicalCandidates,
        maxEvidenceChunks = retrieval.maxEvidenceChunks,
        maxPerDocument = retrieval.maxChunksPerDocument,
        maxPerPage = retrieval.maxChunksPerPage
    ).withBenchmarkBinding(binding)

    fun retrievalRanker(): HybridRetrievalRanker = HybridRetrievalRanker(
        lexicalSource = SqliteFts5Bm25CandidateSource(),
        rrfK = retrieval.rrfK,
        mmrLambda = retrieval.mmrLambda
    )

    fun requirePersonaWordLimit(limit: Int) {
        require(limit == persona.focusNoteMaxWords) { "rag_persona_runtime_limit_mismatch" }
    }

    companion object {
        const val ASSET_PATH = "ai/rag_runtime_contract.json"
        const val E5_MODEL = "intfloat/multilingual-e5-small"
        const val E5_REVISION = "614241f622f53c4eeff9890bdc4f31cfecc418b3"
        const val DEFAULT_CHUNK_TARGET_TOKENS = 224
        const val DEFAULT_CHUNK_HARD_MAXIMUM_TOKENS = 256
        const val DEFAULT_CHUNK_OVERLAP_TOKENS = 32
        const val DEFAULT_CANDIDATE_LIMIT = 30
        const val DEFAULT_RRF_K = 60
        const val DEFAULT_MMR_LAMBDA = 0.75f
        const val DEFAULT_MAX_EVIDENCE_CHUNKS = 4
        const val DEFAULT_MAX_CHUNKS_PER_DOCUMENT = 3
        const val DEFAULT_MAX_CHUNKS_PER_PAGE = 2
        const val DEFAULT_FOCUS_NOTE_MAX_WORDS = 1_500
        private const val SQLITE_FTS5_BM25 = "sqlite_fts5_bm25"
        private const val BLOCKED_PRODUCTION_STATUS = "blocked_until_benchmark_and_physical_validation"
        private const val ABSTAIN = "abstain"
        private val SHA256 = Regex("^[a-f0-9]{64}$")
    }
}

class AssetRagRuntimeContract(private val context: Context) {
    fun load(): RagRuntimeContract = context.assets.open(RagRuntimeContract.ASSET_PATH)
        .bufferedReader()
        .use { RagRuntimeContractJson.parse(it.readText()) }

    companion object {
        internal fun parseJson(raw: String): RagRuntimeContract = RagRuntimeContractJson.parse(raw)
    }
}
